CONTRACTS: Dict[str, Dict[str, Any]] = {"computer": COMPUTER_V2_CONTRACT, "browser": BROWSER_CONTRACT}


def member_spec(toolset: str, member: str) -> Optional[Dict[str, Any]]:
    """The contract row for one member, or None when it does not exist."""
    for row in CONTRACTS[toolset]["members"]:
        if row["name"] == member:
            return row
    return None
